import { FACILITY_ID, apiRequest } from "./client";

export function verifyAdminPassword(password) {
  return apiRequest(`/api/v1/facilities/${FACILITY_ID}/verify-password`, {
    method: "POST",
    body: { password },
    fallbackError: "Could not verify password",
  });
}

export function changeAdminPassword({ oldPassword, newPassword, confirmPassword }) {
  return apiRequest(`/api/v1/facilities/${FACILITY_ID}/password`, {
    method: "PUT",
    body: { oldPassword, newPassword, confirmPassword },
    fallbackError: "Could not change password",
  });
}
