import React, { useMemo, useEffect } from "react";
import LevelAvatar from "./LevelAvatar";
import TeamBadge, { resolveTeamBadgeDisplay } from "./TeamBadge";

export default function PlayersModal({
  open,
  courtName,
  players,
  onClose,
  onSpeak,
  variant,
  teamsModeEnabled = false,
  teams = [],
  teamsSettings = {},
  courtTeamMeta = null,
}) {
  // 🧠 Always call hooks — even if modal is closed
  useEffect(() => {
    const onKey = (e) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  // modal uses a clean, static background


  const sortedPlayers = useMemo(() => {
    const teamOrder = { blue: 0, green: 1 };
    return [...players].sort((a, b) => {
      const aRank = teamOrder[a.team] ?? 2;
      const bRank = teamOrder[b.team] ?? 2;
      if (aRank !== bRank) return aRank - bRank;
      return (a.name || "").localeCompare(b.name || "");
    });
  }, [players]);

  // 🧱 If not open, render nothing
  if (!open) return null;

  // Render NEW Display Variant — Dark Premium
  if (variant === "display") {
    const courtNum = courtName.replace(/[^0-9]/g, "") || "?";
    return (
      <div className="fixed inset-0 z-50 flex items-center justify-center p-6 animate-fadeIn">
        {/* Dark backdrop with subtle vignette */}
        <div
          className="absolute inset-0 backdrop-blur-md"
          style={{ background: 'radial-gradient(ellipse at center, rgba(15,25,35,0.97) 0%, rgba(9,21,34,0.99) 100%)' }}
          onClick={onClose}
        />

        {/* Modal container */}
        <div
          className="relative w-full max-w-[98vw] h-[95vh] rounded-3xl overflow-hidden flex"
          style={{ background: 'linear-gradient(160deg, #1a2634 0%, #131f2d 100%)', border: '1px solid #2a3f55', boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.7)' }}
        >
          {/* Teal top accent stripe */}
          <div className="absolute top-0 left-0 right-0 h-1" style={{ background: 'linear-gradient(90deg, #00A3E0, #007BB5, #00A3E0)' }} />

          {/* Left: Giant Court Number */}
          <div className="w-[22%] flex flex-col items-center justify-center border-r border-pt-dark-border px-2 relative overflow-hidden">
            {/* subtle background radial */}
            <div className="absolute inset-0 pointer-events-none" style={{ background: 'radial-gradient(circle at 50% 60%, rgba(255,255,255,0.05) 0%, transparent 70%)' }} />
            <span
              className="font-condensed font-black text-white leading-none select-none text-center"
              style={{ fontSize: 'clamp(9rem, 28vw, 28rem)', color: 'white', textShadow: '0 0 40px rgba(255,255,255,0.3)' }}
            >
              {courtNum}
            </span>
          </div>

          {/* Right: Players List */}
          <div className="flex-1 flex flex-col px-10 py-8">
            {/* Player rows */}
            <div className="flex-1 flex flex-col justify-center gap-3 overflow-hidden">
              {sortedPlayers.length === 0 ? (
                <div className="text-center font-condensed uppercase text-white/20 text-[clamp(1.5rem,5vh,3rem)]">
                  Empty Court
                </div>
              ) : (
                sortedPlayers.map((p) => {
                  const metaSide =
                    p.team === "green"
                      ? courtTeamMeta?.sideA
                      : p.team === "blue"
                        ? courtTeamMeta?.sideB
                        : null;
                  const teamColor =
                    metaSide?.color ||
                    (p.team === "green" ? "#22C55E" : p.team === "blue" ? "#60A5FA" : "#00A3E0");
                  const teamLabel =
                    metaSide?.name ||
                    (p.team === "green" ? "Green" : p.team === "blue" ? "Blue" : null);
                  const tb = resolveTeamBadgeDisplay(
                    p,
                    courtTeamMeta,
                    teamsModeEnabled,
                    teams,
                    teamsSettings?.unassignedLabel
                  );
                  return (
                    <div
                      key={p.id}
                      className="flex-1 flex items-center px-6 py-4 rounded-3xl gap-6 transition-transform hover:scale-[1.01]"
                      style={{
                        background: 'rgba(255,255,255,0.08)',
                        border: `2px solid rgba(${p.team === "green" ? "34,197,94" : p.team === "blue" ? "96,165,250" : "255,255,255"},0.3)`,
                        borderLeft: `6px solid ${teamColor}`,
                      }}
                    >
                      {/* Avatar */}
                      <div
                        className="shrink-0 rounded-3xl overflow-hidden flex items-center justify-center bg-pt-dark-card"
                        style={{
                          width: 'clamp(6rem, 16vh, 13rem)',
                          height: 'clamp(6rem, 16vh, 13rem)',
                          border: `3px solid ${teamColor}`,
                          boxShadow: `0 0 15px ${teamColor}60`,
                        }}
                      >
                        {p.imageUrl || p.photo ? (
                          <img src={p.imageUrl || p.photo} alt={p.name} className="w-full h-full object-cover" />
                        ) : (
                          <span style={{ fontSize: 'clamp(2rem, 5vh, 4rem)' }}>😎</span>
                        )}
                      </div>

                      {/* Name */}
                      <div className="flex-1 min-w-0 flex flex-col justify-center h-full text-center gap-2">
                        {tb && (
                          <TeamBadge letter={tb.letter} color={tb.color} title={tb.title} className="mx-auto text-sm min-w-[2rem] h-8 px-2 rounded-lg" />
                        )}
                        <span
                          className="font-condensed font-black text-white uppercase truncate leading-none"
                          style={{ fontSize: 'clamp(10rem, 12vh, 8.5rem)', textShadow: '0 2px 10px rgba(0,0,0,0.5)' }}
                        >
                          {p.name}
                        </span>
                        {teamLabel && teamsModeEnabled && (
                          <span
                            className="font-display text-white/70 uppercase tracking-widest text-[clamp(0.75rem,2vw,1rem)]"
                          >
                            {teamLabel}
                          </span>
                        )}
                      </div>
                    </div>
                  );
                })
              )}
            </div>
          </div>
        </div>
      </div>
    );
  }


  // Render DEFAULT / EXISTING Modal
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/40" onClick={onClose} />

      {/* Modal Card */}
      <div className="relative bg-white rounded-xl shadow-3xl w-[min(98vw,1080px)] p-8 animate-[fadeIn_120ms_ease-out] flex gap-6 scale-[0.85] origin-center">
        {/* Left: Large Court Number */}
        <div className="flex-shrink-0 flex items-center justify-center w-1/4">
          <h1 className="text-[25rem] font-extrabold text-[#1E3A8A] leading-none select-none">
            {courtName.replace(/[^0-9]/g, "") || "?"}
          </h1>
        </div>

        {/* Right: Player List + Controls */}
        <div className="flex-1">
          {/* Header */}
          <div className="relative mb-5 text-center">
            <h3 className="text-4xl font-bold text-[#1E3A8A]">
              {courtName} — Players
            </h3>
            <button
              onClick={onClose}
              className="absolute right-0 top-0 text-gray-500 hover:text-gray-700 text-base"
              aria-label="Close"
            >
              ✖
            </button>
          </div>

          {/* Player list */}
          <ul className="space-y-2 mb-4">
            {players.length === 0 ? (
              <li className="text-gray-600 text-lg">No players assigned.</li>
            ) : (
              sortedPlayers.map((p) => {
                const teamClass =
                  p.team === "green"
                    ? "bg-gradient-to-r from-green-100 via-green-50 to-white border border-green-200"
                    : p.team === "blue"
                      ? "bg-gradient-to-r from-blue-100 via-blue-50 to-white border border-blue-200"
                      : "bg-white border border-gray-200";
                const teamLabel = p.team === "green" ? "Green Team" : p.team === "blue" ? "Blue Team" : null;
                return (
                  <li
                    key={p.id}
                    className={`relative overflow-hidden flex items-center justify-between rounded-lg px-4 py-3 ${teamClass}`}
                  >
                    <div className="flex items-center w-full relative justify-between z-10">
                      <div className="flex items-center gap-5">
                        <LevelAvatar
                          src={p.imageUrl || p.photo || p.avatarUrl || null}
                          alt={p.name}
                          fallback={p.name}
                          frameColor={p.team === "green" ? "#22C55E" : p.team === "blue" ? "#60A5FA" : "#00A3E0"}
                          size={120}
                          ring={5}
                          gap={3}
                        />
                        <div className="flex flex-col gap-1">
                          <span
                            className="text-5xl md:text-[6rem] font-extrabold text-[#1E3A8A] leading-none break-words text-left"
                            style={{ textShadow: "0 2px 4px rgba(0,0,0,0.25)" }}
                          >
                            {p.name}
                          </span>
                          {teamLabel && (
                            <span
                              className={`w-max text-xs font-semibold uppercase tracking-wide px-2 py-0.5 rounded-full ${p.team === "green" ? "bg-green-600/90 text-white" : "bg-blue-700/90 text-white"
                                }`}
                            >
                              {teamLabel}
                            </span>
                          )}
                        </div>
                      </div>
                    </div>

                    <span className="relative z-10 text-xs text-gray-700 whitespace-nowrap bg-white/70 rounded px-2 py-1">
                      ({p.matches})
                    </span>

                  </li>
                );
              })
            )}
          </ul>

          {/* Buttons */}
          <div className="flex items-center justify-end gap-2">
            <button
              onClick={onSpeak}
              className="bg-[#1E3A8A] text-white px-4 py-2 rounded hover:bg-[#243c90] text-sm"
            >
              🔊 Speak Names
            </button>
            <button
              onClick={onClose}
              className="px-3 py-2 rounded border text-sm hover:bg-gray-50"
            >
              Close
            </button>
          </div>
        </div>
      </div>
    </div >
  );
}

